import React, { useState, useEffect, useContext } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { AppContext } from '../context/AppContext';
import api from '../utils/api';

const BookDetailsPage = () => {
  const { id } = useParams();
  const [book, setBook] = useState(null);
  const [loading, setLoading] = useState(true);
  const { user, buyBook } = useContext(AppContext);
  const navigate = useNavigate();

  useEffect(() => {
    fetchBook();
  }, [id]);

  const fetchBook = async () => {
    try {
      const res = await api.get(`/books/${id}`);
      setBook(res.data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleBuy = async () => {
    if (!user) {
      alert('Please login to buy books');
      navigate('/login');
      return;
    }
    const success = await buyBook(book._id);
    if (success) {
      alert('Book purchased successfully!');
      navigate('/orders');
    }
  };

  if (loading) return <p className="text-center text-xl py-12">Loading...</p>;
  if (!book) return <p className="text-center text-xl py-12">Book not found</p>;

  return (
    <div className="max-w-4xl mx-auto mt-12 px-4">
      <div className="bg-white p-8 rounded-lg shadow-lg">
        <img src={book.image} alt={book.title} className="w-full h-96 object-cover rounded-lg mb-6" />
        <h1 className="text-4xl font-bold mb-2 text-gray-800">{book.title}</h1>
        <p className="text-xl text-gray-600 mb-4">by {book.author}</p>
        <p className="text-3xl font-bold text-green-600 mb-4">₹{book.price}</p>
        {book.category && <p className="text-gray-700 mb-4"><span className="font-semibold">Category:</span> {book.category}</p>}
        <p className="text-lg leading-relaxed text-gray-700 mb-8">{book.description}</p>
        <button onClick={handleBuy} className="px-8 py-3 bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-600 hover:to-emerald-700 text-white rounded-lg text-lg font-semibold transition-all">
          Buy Now - ₹{book.price}
        </button>
      </div>
    </div>
  );
};

export default BookDetailsPage;
